// a model of a profile that carries wargear GW gives its own base is on that base (baseWith: the Skitarii Rangers' transuranic arquebus)
const withGear = (s, u, line) => { const g = ((u.gear || [])[line] || []).map(norm), k = Object.keys(s.baseWith || {}).find(x => g.includes(norm(x))); return k ? s.baseWith[k] : s.base; };
function baseOf(u, name, line){
