  let rows = u.stats.map(s => ({ s, n:norm(s.name.replace(/ ×\d+$/, '')) }));
  const nm = norm(baseName(name));
  // in an attached unit the first models lines are the characters; the others are bodyguard models
  const nc = charsOf(u).length;
